/**
 * Local platform folder is generated by 'cap add android'.
 * Register the in-repository Android SAF plugin before 'cap sync android'.
 * Never overwrite a customized MainActivity silently.
 */
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";

const appId = "app.lovable.logogridstudio";
const directory = resolve("android/app/src/main/java", ...appId.split("."));
const mainFile = resolve(directory, "MainActivity.java");
const pluginFile = resolve(directory, "NativeDocumentsPlugin.java");
const source = resolve("native-android/NativeDocumentsPlugin.java");
if (!existsSync(mainFile) || !existsSync(source)) {
  throw new Error("Run 'bunx cap add android' before installing NativeDocuments");
}
const original = readFileSync(mainFile, "utf8");
if (!original.includes("package " + appId + ";")) {
  throw new Error("Unexpected Android app ID; refusing to modify MainActivity");
}
if (!original.includes("registerPlugin(NativeDocumentsPlugin.class)")) {
  const pattern = /public class MainActivity extends BridgeActivity\s*\{\s*\}/;
  if (!pattern.test(original)) {
    throw new Error("Customized MainActivity: register NativeDocumentsPlugin manually");
  }
  const replacement = "public class MainActivity extends BridgeActivity {\n" +
    "  @Override public void onCreate(android.os.Bundle state) {\n" +
    "    registerPlugin(NativeDocumentsPlugin.class);\n" +
    "    super.onCreate(state);\n" +
    "  }\n" +
    "}";
  writeFileSync(mainFile, original.replace(pattern, replacement));
}
mkdirSync(dirname(pluginFile), { recursive: true });
copyFileSync(source, pluginFile);
console.log("Installed NativeDocuments SAF plugin");
